draw((0,0)--(5,0),linewidth(1),Arrows);
draw((0,.8)--(0,1),linewidth(1));
draw((1,.8)--(1,1),linewidth(1));
draw((2,.8)--(2,1),linewidth(1));
draw((3,.8)--(3,1),linewidth(1));
draw((4,.8)--(4,1),linewidth(1));
draw((5,.8)--(5,1),linewidth(1));
